import { defineComponent, PropType } from 'vue';
import { inversifyContainer } from '../../../inversify/container';
import { getPrizeLeagueSkinName } from '../prize-league-utils';

export type MenuBarTab = 'leagues' | 'prizes' | 'leaderboard';

export default defineComponent({
    name: 'MenuBar',
    props: {
        activeTab: {
            type: String as PropType<MenuBarTab>,
            required: true
        },
        tournamentId: {
            type: String,
            required: false,
            default: ''
        }
    },
    data() {
        return {
            skinName: getPrizeLeagueSkinName()
        };
    },
    emits: ['change-panel'],
    computed: {
        translations() {
            return inversifyContainer.strings.prizeLeague;
        }
    },
    methods: {
        onBackClicked() {
            this.$emit('change-panel', 'tournamentList');
        },
        onTabClicked(tab: MenuBarTab) {
            if (tab === this.activeTab) return;
            this.$emit('change-panel', tab === 'prizes' ? 'prizeList' : 'leaderboard', this.tournamentId);
        }
    }
});
